namespace FireURQ.Porter.Translation;

public static class CSharpVariantRuntime
{
    public const string Source = """
// <auto-generated />
#nullable enable
namespace FireURQ.Runtime
{
    public readonly struct Variant
    {
        private readonly ushort typeCode;
        private readonly object? value;

        private Variant(ushort typeCode, object? value)
        {
            this.typeCode = typeCode;
            this.value = value;
        }

        public ushort TypeCode => typeCode;
        public static Variant Unassigned => default;
        public static Variant Null => new Variant(1, null);

        public static implicit operator Variant(int value) =>
            new Variant(3, value);
        public static implicit operator Variant(double value) =>
            new Variant(5, value);
        public static implicit operator Variant(bool value) =>
            new Variant(11, value);
        public static implicit operator Variant(string value) =>
            new Variant(256, value ?? string.Empty);

        public static implicit operator double(Variant source)
        {
            if (source.typeCode == 11 && source.value is bool boolean)
                return boolean ? -1.0 : 0.0;

            object? data = source.typeCode == 1
                ? global::System.DBNull.Value
                : source.value;
            return global::System.Convert.ToDouble(
                data, global::System.Globalization.CultureInfo.InvariantCulture);
        }

        public static implicit operator string(Variant source)
        {
            object data = source.typeCode == 1
                ? global::System.DBNull.Value
                : source.value ?? string.Empty;
            // DBNull formatting accepts an empty string, unlike a strict
            // Delphi Null conversion. Preserve the incompatible value
            // for the CLR cast instead of passing it to the formatter.
            if (source.typeCode == 1)
                return (string)data;

            return (string)global::System.Convert.ChangeType(
                data, typeof(string),
                global::System.Globalization.CultureInfo.InvariantCulture);
        }

        public static bool operator ==(Variant left, Variant right)
        {
            // Default Delphi NullEqualityRule: ncrLoose.
            if (left.typeCode == 1 || right.typeCode == 1)
                return left.typeCode == 1 && right.typeCode == 1;

            if ((left.typeCode == 256 && right.typeCode is 0 or 256) ||
                (right.typeCode == 256 && left.typeCode == 0))
                return global::System.String.Equals(
                    (string)left, (string)right,
                    global::System.StringComparison.Ordinal);

            return (double)left == (double)right;
        }

        public static bool operator !=(Variant left, Variant right) =>
            !(left == right);

        public override bool Equals(object? other) =>
            other is Variant variant && this == variant;

        public override int GetHashCode()
        {
            if (typeCode == 1)
                return 1;
            if (typeCode == 256)
            {
                string text = (string)this;
                if (text.Length == 0)
                    return 0.0.GetHashCode();
                if (double.TryParse(
                    text,
                    global::System.Globalization.NumberStyles.Float |
                    global::System.Globalization.NumberStyles.AllowThousands,
                    global::System.Globalization.CultureInfo.InvariantCulture,
                    out double number))
                    return number.GetHashCode();
                return global::System.StringComparer.Ordinal.GetHashCode(text);
            }
            return ((double)this).GetHashCode();
        }

        public bool TryGetInteger(out int result)
        {
            result = value is int number ? number : default;
            return typeCode == 3 && value is int;
        }

        public bool TryGetDouble(out double result)
        {
            result = value is double number ? number : default;
            return typeCode == 5 && value is double;
        }

        public bool TryGetBoolean(out bool result)
        {
            result = value is bool boolean && boolean;
            return typeCode == 11 && value is bool;
        }

        public bool TryGetString(out string result)
        {
            result = value as string ?? string.Empty;
            return typeCode == 256 && value is string;
        }
    }

    public static class DelphiVariants
    {
        public static Variant Null => Variant.Null;
        public static Variant Unassigned => Variant.Unassigned;

        public const ushort varEmpty = 0;
        public const ushort varNull = 1;
        public const ushort varInteger = 3;
        public const ushort varDouble = 5;
        public const ushort varBoolean = 11;
        public const ushort varString = 256;

        public static ushort VarType(Variant value) => value.TypeCode;
        public static bool VarIsEmpty(Variant value) =>
            value.TypeCode == varEmpty;
        public static bool VarIsNull(Variant value) =>
            value.TypeCode == varNull;
        public static bool VarIsNumeric(Variant value) =>
            value.TypeCode is varInteger or varDouble;
        public static void VarClear(ref Variant value) =>
            value = Variant.Unassigned;
    }
}
""";
}